SELECT Intervenant.codint,Intervention.typint,Intervention.datintpre,Site.numsit,Site.nomsit,Site.typsit,Site.vilsit,parametre.datdeb,parametre.datfin,Client.logcli,Client.nomcli,Intervention.dirint FROM [Client],[Site],[parametre],[Intervenant],[Intervention] WHERE (((Intervention.typint)="1") And ((Intervention.datintpre) Is Not Null And (Intervention.datintpre) Between parametre!datdeb And parametre!datfin) And ((Intervention.datint) Is Null)) 
